// The supplied arena has only slots 0-6. Add the missing slot on the server
// without altering or redistributing a modified copy of the original map.
function EnsureArenaGroundsEighthStart()
{
    local HPVersusStart S;
    local HPVersusStart Anchor;
    local HPVersusArenaStart NewStart;
    local Vector Candidate;
    local Vector HitLocation;
    local Vector HitNormal;
    local Actor Floor;

    if (Role != ROLE_Authority || MaxPlayers < 8
        || InStr(Caps(string(Level)), "ARENA_GROUNDS_HUB") < 0
        || VersusStartIndexExists(7))
        return;
    foreach AllActors(Class'HPVersusStart', S)
        if (S.bEnabled && S.VersusSpawnIndex == 0)
        {
            Anchor = S;
            break;
        }
    if (Anchor == None)
    {
        Log("HPVersusArenaStart ERROR: slot 0 anchor is missing");
        return;
    }
    Candidate = Anchor.Location + vect(0,-224,0);
    Floor = Trace(HitLocation, HitNormal,
        Candidate - vect(0,0,512), Candidate + vect(0,0,128), False);
    if (Floor == None || HitNormal.Z < 0.7)
    {
        Log("HPVersusArenaStart ERROR: no safe floor at " $ string(Candidate));
        return;
    }
    Candidate.Z = HitLocation.Z + Anchor.CollisionHeight;
    NewStart = Spawn(Class'HPVersusArenaStart',,, Candidate, Anchor.Rotation);
    if (NewStart == None)
    {
        Log("HPVersusArenaStart ERROR: spawn failed at " $ string(Candidate));
        return;
    }
    NewStart.VersusSpawnIndex = 7;
    NewStart.bEnabled = True;
    Log("HPVersusArenaStart added slot=7 start=" $ string(NewStart)
        $ " location=" $ string(NewStart.Location)
        $ " anchor=" $ string(Anchor));
}

